INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass alle Kunststoffe wiederverwertbar sind?', 2, '[{"text": "Nein", "correct": true, "because": "Manche Kunststoffe sind nicht recycelbar"}, {"text": "Ja", "correct": false, "because": "Technische und wirtschaftliche Grenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Material wird am häufigsten wiederverwertet?', 3, '[{"text": "Metall", "correct": true, "because": "Hohe Wiederverwertungsrate durch Schmelzen"}, {"text": "Holz", "correct": false, "because": "Begrenzte Wiederverwendung"}, {"text": "Textilien", "correct": false, "because": "Komplexe Verarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse sind für die Wiederverwertung von Papier entscheidend?', 5, '[{"text": "Entfernen von Verunreinigungen", "correct": true, "because": "Sichert saubere Fasern"}, {"text": "Zellstoffaufbereitung", "correct": true, "because": "Macht Papier wiederverwendbar"}, {"text": "Farbstoffzugabe", "correct": false, "because": "Nur für Aussehen"}, {"text": "Hochglanzbeschichtung", "correct": false, "because": "Erschwert Wiederverwertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Glas ist unbegrenzt wiederverwertbar. b) Es verliert dabei an Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Glas behält Qualität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung eines Wiederverwertungsprozesses?', 4, '[{"text": "Materialtrennung", "correct": false, "because": "Kern für Effizienz"}, {"text": "Energieverbrauch", "correct": false, "because": "Beeinflusst Kosten"}, {"text": "Verpackungsdesign", "correct": true, "because": "Sekundär für Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Plastikflaschen immer in den gleichen Kreislauf zurückkehren?', 2, '[{"text": "Nein", "correct": true, "because": "Oft Downcycling zu anderen Produkten"}, {"text": "Ja", "correct": false, "because": "Qualitätsverlust möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode verbessert die Wiederverwertung von Elektronik?', 4, '[{"text": "Modulares Design", "correct": true, "because": "Erleichtert Demontage"}, {"text": "Maximale Komprimierung", "correct": false, "because": "Erschwert Trennung"}, {"text": "Einheitliche Farben", "correct": false, "because": "Kein technischer Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass wiederverwertetes Papier immer schlechter ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Qualität hängt von Verarbeitung ab"}, {"text": "Ja", "correct": false, "because": "Moderne Technik erhält Qualität"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jede Art von Glas wiederverwertbar?', 2, '[{"text": "Nein", "correct": true, "because": "Z. B. Sicherheitsglas problematisch"}, {"text": "Ja", "correct": false, "because": "Verunreinigungen schwierig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen einen Wiederverwertungsprozess effizient?', 5, '[{"text": "Saubere Trennung", "correct": true, "because": "Vermeidet Verunreinigungen"}, {"text": "Automatisierte Sortierung", "correct": true, "because": "Spart Zeit"}, {"text": "Hohe Temperaturen", "correct": false, "because": "Nur bei Metallen"}, {"text": "Manuelle Kontrolle", "correct": false, "because": "Zu langsam"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wiederverwertung von Kunststoffen?', 4, '[{"text": "Sortierung nach Typ", "correct": true, "because": "Sichert reine Materialien"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Verpackung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Metalle sind hoch recycelbar. b) Sie verlieren immer an Qualität.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Metalle behalten Eigenschaften"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen effizienten Wiederverwertungsprozess?', 3, '[{"text": "Sortieranlagen", "correct": false, "because": "Fördern Präzision"}, {"text": "Reinigungssysteme", "correct": false, "because": "Vermeiden Verunreinigungen"}, {"text": "Dekorative Verpackung", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich bei der Wiederverwertung von Batterien vorgehe?', 4, '[{"text": "Spezialisierte Rücknahmesysteme nutzen", "correct": true, "because": "Sichert sichere Verarbeitung"}, {"text": "Mit Hausmüll entsorgen", "correct": false, "because": "Umweltgefährdend"}, {"text": "Manuell zerlegen", "correct": false, "because": "Zu riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Wiederverwertung immer teurer als Neuproduktion ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kosteneffizient bei Skalierung"}, {"text": "Ja", "correct": false, "because": "Ressourcen einsparen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, Wiederverwertung zu fördern?', 4, '[{"text": "Kreislaufwirtschaft", "correct": true, "because": "Maximiert Materialnutzung"}, {"text": "Lineare Produktion", "correct": false, "because": "Verschwendet Ressourcen"}, {"text": "Einwegprodukte", "correct": false, "because": "Erschwert Wiederverwertung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist wiederverwertetes Plastik immer schlechter?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität abhängig von Verarbeitung"}, {"text": "Ja", "correct": false, "because": "Technik verbessert Ergebnisse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Wiederverwertung von Aluminium?', 5, '[{"text": "Energiesparnis", "correct": true, "because": "Weniger Energie als Neuproduktion"}, {"text": "Reduzierter Abfall", "correct": true, "because": "Hält Material im Kreislauf"}, {"text": "Höhere Dichte", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Kernvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Wiederverwertung von Textilien unwichtig?', 3, '[{"text": "Materialzusammensetzung", "correct": false, "because": "Entscheidend für Verarbeitung"}, {"text": "Trennung von Fasern", "correct": false, "because": "Sichert Qualität"}, {"text": "Modetrend", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, um Elektronik effizient wiederzuverwerten?', 4, '[{"text": "Komponenten trennen", "correct": true, "because": "Ermöglicht Wiederverwendung"}, {"text": "Alles schreddern", "correct": false, "because": "Zerstört wertvolle Teile"}, {"text": "In den Hausmüll", "correct": false, "because": "Umweltgefährdend"}]');
